const session = $('Fetch Session').first().json;

const systemPrompt = `You are a senior technical recruitment consultant conducting a structured technical screening interview. Your job is to generate exactly 8 technical questions for a candidate being assessed for a specific role.

Questions must be:
- Technically specific to the role requirements, not generic
- Progressive in difficulty (questions 1-3 easy, 4-6 medium, 7-8 hard)
- Answerable verbally in 1-3 minutes each
- Designed to reveal genuine technical depth, not just theoretical knowledge
- Mix of: conceptual understanding, practical application, problem-solving, and experience-based

For each question provide:
- The question text (clear, specific, conversational)
- The expected answer (what a strong candidate should cover — bullet points of key concepts)
- Difficulty: easy / medium / hard
- What a poor answer looks like (so screener can identify weak responses)

Return ONLY a valid JSON array, no markdown, no preamble:
[
  {
    "question_number": 1,
    "question_text": "...",
    "expected_answer": "...",
    "poor_answer_indicators": "...",
    "difficulty": "easy"
  }
]`;

const userPrompt = `ROLE BEING FILLED:
Title: ${session.role_title}
Company: ${session.company_name ?? session.inferred_client_name ?? 'Confidential'}
Discipline: ${session.job_discipline}
Location: ${session.location_city}, ${session.location_state}
Requirements: ${session.employee_instruction ?? 'Not specified'}
Pain point: ${session.pain_hypothesis ?? 'Not specified'}

CANDIDATE BEING SCREENED:
Name: ${session.candidate_name}
Discipline: ${session.candidate_discipline}
Experience: ${session.years_experience}
Headline: ${session.headline}
Strengths: ${session.strengths ?? 'Not available'}
Concerns: ${session.concerns_or_gaps ?? 'Not available'}
Best fit roles: ${session.best_fit_role_types ?? 'Not available'}
AI compatibility score: ${session.ai_compatibility_score ?? 'Not scored'}/100
AI match reasoning: ${session.ai_match_reasoning ?? 'Not available'}
AI match concerns: ${session.ai_match_concerns ?? 'Not available'}

Generate 8 technical questions tailored specifically to assess this candidate for this role. Focus on areas where the AI noted concerns, and probe the strengths to verify depth.`;

return [{
  json: {
    systemPrompt,
    userPrompt,
    sessionId: session.session_id,
    candidateId: session.candidate_id,
    jobId: session.job_id
  }
}];

const data = $('Build Question Prompt').first().json;

const body = {
  model: "claude-sonnet-4-5",
  max_tokens: 4000,
  system: data.systemPrompt,
  messages: [
    {
      role: "user",
      content: data.userPrompt
    }
  ]
};

return [{
  json: {
    body: JSON.stringify(body),
    sessionId: data.sessionId,
    candidateId: data.candidateId,
    jobId: data.jobId
  }
}];

const response = $('Claude Generate Questions').first().json;
const metadata = $('Build Request Body').first().json;

const rawText = response.content
  .filter(block => block.type === 'text')
  .map(block => block.text)
  .join('');

const cleaned = rawText
  .replace(/```json\n?/g, '')
  .replace(/```\n?/g, '')
  .trim();

const questions = JSON.parse(cleaned);

if (!Array.isArray(questions)) {
  throw new Error('Expected array of questions');
}

return questions.map(q => ({
  json: {
    session_id: metadata.sessionId,
    question_number: q.question_number,
    question_text: q.question_text,
    expected_answer: q.expected_answer,
    poor_answer_indicators: q.poor_answer_indicators,
    difficulty: q.difficulty
  }
}));
